import { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function QuizPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const domain = searchParams.get('domain') || 'General Technology';
  
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(true);

  // 🔥 FETCH DYNAMIC QUESTIONS FROM BACKEND
  useEffect(() => {
    const fetchQuestions = async () => {
      setLoading(true);
      try {
        const res = await fetch("http://localhost:5000/api/quiz/generate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ domain })
        });
        const data = await res.json();
        setQuestions(data);
      } catch (err) {
        console.error("Failed to load questions", err);
      } finally {
        setLoading(false);
      }
    };

    fetchQuestions();
  }, [domain]);

  const score = questions.reduce((acc, q) => 
    acc + (selected[q.id] === q.answer ? 1 : 0), 0
  );

  if (loading) return <div className="p-10 text-center text-xl">✨ AI is generating your unique quiz...</div>;

  return (
    <div className="max-w-4xl mx-auto p-4 space-y-8">
      <div className="rounded-[2rem] border p-8 bg-white shadow-xl">
        <h2 className="text-3xl font-bold capitalize">{domain.replace('-', ' ')} Quiz</h2>
        
        <div className="mt-8 space-y-6">
          {questions.map((q, index) => (
            <div key={q.id} className="p-6 border rounded-3xl bg-slate-50">
              <p className="font-semibold text-lg mb-4">{index + 1}. {q.question}</p>
              <div className="grid gap-3 sm:grid-cols-2">
                {q.options.map((opt) => (
                  <button
                    key={opt}
                    disabled={submitted}
                    onClick={() => setSelected(prev => ({ ...prev, [q.id]: opt }))}
                    className={`p-4 text-left border rounded-2xl transition ${
                      selected[q.id] === opt ? 'bg-teal-500 text-white border-teal-500' : 'bg-white hover:border-teal-300'
                    } ${submitted && opt === q.answer ? 'border-green-500 ring-2 ring-green-200' : ''}`}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div className="mt-8">
          {!submitted ? (
            <Button 
              onClick={() => setSubmitted(true)} 
              disabled={Object.keys(selected).length < questions.length}
            >
              Submit Quiz
            </Button>
          ) : (
            <div className="space-y-4">
              <div className="text-2xl font-bold text-teal-600">Final Score: {score} / {questions.length}</div>
              <Button onClick={() => navigate(`/roadmap/${domain}`)} className="w-full">
                Generate Roadmap →
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
